head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/********************************************************** 
 * 종목검색을 위한 JS 
 * 유명현
 ***********************************************************/

stFocusGrid = false;
stSearchId = ""; //종목코드를 되받을 엘리멘트
stSearchNm = ""; //종목명을 되받을 엘리멘트
stSearchIsurId = ""; //발행사코드엘리멘트
stSearchIsurNm = ""; //발행사명엘리멘트

stSearchId_js = ""; //종목코드를 되받을 js변수
stSearchNm_js = ""; //종목명을 되받을 js변수
stSearchIsurId_js = ""; //발행사코드을 되받을 js변수
stSearchIsurNm_js = ""; //발행사명을 되받을 js변수

stSearchKind = ""; //ST:주식, EW:주식워런트증권, BC:수익증권, FU:선물
stSearchMarket = ""; //시장구분 0:전체 1:유가 2:코스닥
stSearchOpt = ""; //A:전체, Y:상장, D:상장안됨,N:상장폐지

/**
 * @method
 * @name JongmokSearch_Reset
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.JongmokSearch_Reset = function() {
    scwin.stSearchId = "";
    scwin.stSearchNm = "";
    scwin.stSearchIsurId = "";
    scwin.stSearchIsurNm = "";
    scwin.stSearchId_js = "";
    scwin.stSearchNm_js = "";
    scwin.stSearchIsurId_js = "";
    scwin.stSearchIsurNm_js = "";
    scwin.stSearchKind = "";
    scwin.stSearchMarket = "";
    scwin.stSearchOpt = "";
};
/**
 * @method
 * @name JongmokSearch
 * @description desc
 * @param {string} SearchId desc
 * @param {string} SearchNm desc
 * @param {string} SearchKind desc
 * @param {string} SearchMarket desc
 * @param {string} SearchOpt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.JongmokSearch = async function(SearchId, SearchNm, SearchKind, SearchMarket, SearchOpt) {
    //주식 & 선물용 검색
    scwin.JongmokSearch_Reset(); //종목찾기 초기화
    scwin.stSearchId = SearchId;
    scwin.stSearchNm = SearchNm;
    scwin.stSearchKind = SearchKind;
    scwin.stSearchMarket = SearchMarket;
    scwin.stSearchOpt = SearchOpt;
    if (scwin.stSearchKind == "FU") {
        //선물용
        await $c.frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00006.gfm", "종목검색창", 100, 0, 295, 400, "tool");
    } else {
        //주식
        //주권에서 투자회사 ,ETF종목까지 확장하기 위해 주석처리 2009.02.26
        /*
        if (stSearchMarket == "0") {
        	frame.CreateDialogFrame("virWinSave",  "/common/ULDCOM00003.gfm" , "종목검색창", 100, 0, 295, 400, "tool");
        }else{
        	frame.CreateDialogFrame("virWinSave",  "/common/ULDCOM00003_1.gfm" , "종목검색창", 100, 0, 295, 400, "tool");
        }
        */
        await $c.frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00003.gfm", "종목검색창", 100, 0, 315, 420, "tool");
    }
};
/**
 * @method
 * @name JongmokSearch2
 * @description desc
 * @param {string} SearchId desc
 * @param {string} SearchNm desc
 * @param {string} SearchIsurId desc
 * @param {string} SearchIsurNm desc
 * @param {string} SearchKind desc
 * @param {string} SearchMarket desc
 * @param {string} SearchOpt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.JongmokSearch2 = async function(SearchId, SearchNm, SearchIsurId, SearchIsurNm, SearchKind, SearchMarket, SearchOpt) {
    //ELW,수익증권용 검색
    scwin.JongmokSearch_Reset(); //종목찾기 초기화
    scwin.stSearchId = SearchId;
    scwin.stSearchNm = SearchNm;
    scwin.stSearchIsurId = SearchIsurId;
    scwin.stSearchIsurNm = SearchIsurNm;
    scwin.stSearchKind = SearchKind;
    scwin.stSearchMarket = SearchMarket;
    scwin.stSearchOpt = SearchOpt;
    if (scwin.stSearchKind == "EW") {
        //ELW
        await $c.frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00005.gfm", "종목검색창", 100, 0, 295, 500, "tool");
    } else {
        //수익증권
        await $c.frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00004.gfm", "종목검색창", 100, 0, 295, 500, "tool");
    }
};
/**
 * @method
 * @name JongmokSearch3
 * @description desc
 * @param {string} SearchId desc
 * @param {string} SearchNm desc
 * @param {string} SearchKind desc
 * @param {string} SearchMarket desc
 * @param {string} SearchOpt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.JongmokSearch3 = async function(SearchId, SearchNm, SearchKind, SearchMarket, SearchOpt) {
    scwin.JongmokSearch_Reset(); //종목찾기 초기화
    scwin.stSearchId = SearchId;
    scwin.stSearchNm = SearchNm;
    scwin.stSearchKind = SearchKind;
    scwin.stSearchMarket = SearchMarket;
    scwin.stSearchOpt = SearchOpt;
    await $c.frame.CreateDialogFrame("virWinSave", "/common/ULDCOM00003_1.gfm", "종목검색창", 100, 0, 310, 500, "tool");
};
/**
 * @method
 * @name JongmokSearch_Rtn
 * @description desc
 * @param {string} sval1 desc
 * @param {string} sval2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.JongmokSearch_Rtn = function(sval1, sval2) {
    //주식 & 선물용 검색 return;
    if (scwin.stSearchId_js == "") {
        stSearchId.setValue(sval1);
        if (scwin.stSearchNm != "") {
            stSearchNm.setValue(sval2);
        }
    } else {
        scwin.stSearchId_js = sval1;
        scwin.stSearchNm_js = sval2;
    }
};
/**
 * @method
 * @name JongmokSearch_Rtn2
 * @description desc
 * @param {string} sval1 desc
 * @param {string} sval2 desc
 * @param {string} sval3 desc
 * @param {string} sval4 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.JongmokSearch_Rtn2 = function(sval1, sval2, sval3, sval4) {
    //ELW,수익증권 return;
    if (scwin.stSearchId_js == "") {
        stSearchId.setValue(sval1);
        if (scwin.stSearchNm != "") stSearchNm.setValue(sval2);
        if (scwin.stSearchIsurId != "") stSearchIsurId.setValue(sval3);
        if (scwin.stSearchIsurNm != "") stSearchIsurNm.setValue(sval4);
        //alert(sval4);

    } else {
        scwin.stSearchId_js = sval1;
        scwin.stSearchNm_js = sval2;
        scwin.stSearchIsurId_js = sval3;
        scwin.stSearchIsurNm_js = sval4;
    }
};
/**
 * @method
 * @name isNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isNumber = function(sVal) {
    // 숫자인지 확인
    if (('0' < sVal) || ('9' > sVal)) {
        return true;
    } else {
        return false;
    }
};
